import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a sanitized name.
     *
     * <p>The method removes any query string from {@code name}, normalizes the path,
     * rejects path‑traversal attempts, and guarantees that the resulting file resides
     * strictly within {@code dir}. It also appends a numeric suffix if a file with the
     * same name already exists.</p>
     *
     * @param dir  the base directory where the file should be allocated
     * @param name the requested file name (may come from untrusted sources)
     * @return a {@link File} instance that does not conflict with existing files
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     * @throws SecurityException        if the resolved path is outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject empty names
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be empty");
        }

        // Normalize the path and reject traversal components
        Path rawPath = Paths.get(name).normalize();
        String normalizedName = rawPath.toString();

        // Reject absolute paths or paths containing directory separators
        if (rawPath.isAbsolute()
                || normalizedName.contains("..")
                || normalizedName.contains(File.separator)
                || normalizedName.contains("/")
                || normalizedName.contains("\\")) {
            throw new SecurityException("Invalid file name: " + name);
        }

        try {
            File canonicalDir = dir.getCanonicalFile();
            File file = new File(canonicalDir, normalizedName);

            // Ensure the file stays within the intended directory
            File canonicalFile = file.getCanonicalFile();
            if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + File.separator)) {
                throw new SecurityException("Resolved path escapes the target directory");
            }

            // Resolve name collisions
            String dot = normalizedName.lastIndexOf('.');
            String prefix = dot < 0 ? normalizedName : normalizedName.substring(0, dot);
            String suffix = dot < 0 ? "" : normalizedName.substring(dot);
            int index = 2;
            while (canonicalFile.exists()) {
                String candidateName = prefix + "-" + index++ + suffix;
                file = new File(canonicalDir, candidateName);
                canonicalFile = file.getCanonicalFile();
                if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + File.separator)) {
                    throw new SecurityException("Resolved path escapes the target directory");
                }
            }

            // Create parent directories if necessary
            File parent = canonicalFile.getParentFile();
            if (parent != null && !parent.exists()) {
                parent.mkdirs();
            }

            return canonicalFile;
        } catch (IOException e) {
            // Wrap checked exception into unchecked for callers that expect a File
            throw new RuntimeException("Failed to allocate file", e);
        }
    }

    // other methods

}
```

