import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands archive entries into the specified target directory.
     *
     * <p>This method mitigates path‑traversal attacks by normalizing each entry name,
     * rejecting absolute paths, and ensuring that the resolved path is strictly
     * contained within {@code targetDirectory}. It also sanitizes backslashes
     * (common in Windows paths) and uses {@link Path} APIs for robust path handling.
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to the output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical (real) path of the target directory once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Reject null or empty entry names – they are meaningless and could be abused.
            String rawName = nextEntry.getName();
            if (rawName == null || rawName.isEmpty()) {
                nextEntry = supplier.getNextReadableEntry();
                continue;
            }

            // Normalise path separators to avoid confusion on Windows.
            String sanitizedName = rawName.replace('\\', '/');

            // Reject absolute paths – they would ignore the target directory.
            if (Paths.get(sanitizedName).isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + rawName);
            }

            // Resolve the entry against the target directory and normalise.
            Path entryPath = targetDirPath.resolve(sanitizedName).normalize();

            // Ensure the resolved path is still under the target directory.
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + rawName + " would create file outside of " + targetDirectory);
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the file contents.
                try (OutputStream o = Files.newOutputStream(
                        entryPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
