    /*  Validation helpers                                               */
    /* ------------------------------------------------------------------ */

    /** 
     * A very small whitelist of characters that are allowed in a file
     * name.  This pattern is intentionally restrictive – it accepts
     * alphanumerics, dots, dashes and underscores only.  Any deviation
     * will cause the deserialization to fail.
