     *   <li>No embedded NUL bytes (\"\\0\")</li>
     *   <li>File name matches the whitelist</li>
     *   <li>The file exists and is readable</li>
     * </ul>
     *
     * @param file the file to validate
     * @throws IOException if the file fails any of the checks
     */
    private void validateTempFile(File file) throws IOException {
        if (file == null) {
            throw new IOException("Temporary file reference is null");
        }

        String path = file.getPath();

        // Reject paths containing a NUL byte – this is the core of the
        // vulnerability described in the task.
