import java.lang.reflect.GenericArrayType;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

import com.alibaba.fastjson.JSONArray;
import com.alibaba.fastjson.parser.DefaultJSONParser;
import com.alibaba.fastjson.parser.JSONLexer;
import com.alibaba.fastjson.parser.JSONToken;
import com.alibaba.fastjson.parser.deserializer.ObjectDeserializer;
import com.alibaba.fastjson.util.TypeUtils;

/**
 * A codec that serializes/deserializes object arrays while enforcing strict type safety
 * to mitigate Fastjson deserialization vulnerabilities.
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- *
     * Whitelist of safe component types. Only these types are allowed to be
     * deserialized into arrays. Any other type will cause an exception.
     * --------------------------------------------------------------------- */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES =
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    String.class,
                    Integer.class,
                    Long.class,
                    Double.class,
                    Float.class,
                    Boolean.class,
                    Byte.class,
                    Short.class,
                    Character.class,
                    java.math.BigDecimal.class,
                    java.math.BigInteger.class,
                    java.util.Date.class
            )));

    /* --------------------------------------------------------------------- *
     * Utility method to check whether a component class is considered safe.
     * Primitive types are also allowed because they cannot be instantiated
     * via reflection.
     * --------------------------------------------------------------------- */
    private static boolean isSafeComponentClass(Class<?> cls) {
        return cls.isPrimitive() || SAFE_COMPONENT_TYPES.contains(cls);
    }

    /* --------------------------------------------------------------------- *
     * Deserializes JSON data into an object array of a specified type.
     * --------------------------------------------------------------------- */
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        /* Handle JSON null */
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        /* Handle string literal → byte[] */
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        /* Resolve component class for the array */
        Class<?> componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gArray = (GenericArrayType) type;
            componentType = gArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type objType = parser.getContext().type;

                if (objType instanceof ParameterizedType) {
                    ParameterizedType pType = (ParameterizedType) objType;
                    Type objRawType = pType.getRawType();
                    Type actualType = null;

                    if (objRawType instanceof Class) {
                        TypeVariable<?>[] params = ((Class<?>) objRawType).getTypeParameters();
                        for (int i = 0; i < params.length; ++i) {
                            if (params[i].getName().equals(typeVar.getName())) {
                                actualType = pType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    if (actualType instanceof Class) {
                        componentClass = (Class<?>) actualType;
                    } else {
                        componentClass = Object.class;
                    }
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            Class<?> clazz = (Class<?>) type;
            componentType = componentClass = clazz.getComponentType();
        }

        /* ------------------------------------------------------------------ *
         * Enforce strict type validation. Reject any component type that is
         * not explicitly whitelisted. This prevents deserialization of
         * potentially dangerous types such as java.lang.Class, java.net.URL,
         * or any custom classes that could trigger RMI or other remote
         * execution paths.
         * ------------------------------------------------------------------ */
        if (!isSafeComponentClass(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type '" + componentClass.getName()
                            + "' is not permitted for security reasons.");
        }

        /* Parse the JSON array into a JSONArray */
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        /* Convert JSONArray to a typed Java array */
        return (T) toObjectArray(parser, componentClass, array);
    }

    // other methods omitted for brevity
}
