import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;

/**
 * Utility class that determines whether a SCIM user update request is allowed.
 *
 * <p>Security enhancements:</p>
 * <ul>
 *   <li>Ensures the authenticated user is the owner of the account being updated.</li>
 *   <li>Performs defensive null checks to avoid {@link NullPointerException}s.</li>
 *   <li>Rejects updates that attempt to change the primary email without re‑verification.</li>
 * </ul>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is permitted to modify the SCIM user identified
     * by the path variable. The method now enforces that the authenticated user matches
     * the target user ID and that email changes are only accepted if the new address has
     * been verified.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the update is allowed, {@code false} otherwise
     * @throws IOException if an I/O error occurs while reading the request body
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Verify that the request is made by the account owner
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated user – deny the operation
            return false;
        }

        String authenticatedUserId = principal.getName(); // typically the user ID
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        if (!authenticatedUserId.equals(targetUserId)) {
            // The caller is attempting to modify someone else's account
            return false;
        }

        // 2. Read and parse the request body
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // 3. Retrieve the current user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere)
            return true;
        }

        // 4. Perform field‑by‑field comparison with defensive null handling
        if (!safeEquals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // Email change is not allowed unless the new address is verified
            if (!scimUserFromRequest.isVerified()) {
                return false;
            }
        }

        if (!safeEquals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }

        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }

        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        if (!safeEquals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    /**
     * Utility method that safely compares two strings, handling {@code null} values.
     *
     * @param a first string
     * @param b second string
     * @return {@code true} if both are equal or both are {@code null}
     */
    private boolean safeEquals(String a, String b) {
        return (a == null) ? (b == null) : a.equals(b);
    }
}
